import os; path = r"E:\pycharm\library\templates\catalog\book_list.html"; os.makedirs(os.path.dirname(path), exist_ok=True); html = """{% extends 'base.html' %}\n\n{% block title %}کاتالوگ کتاب‌ها{% endblock %}\n\n{% block content %}\n<div class=""card p-4 shadow-sm mb-4"">\n    <h3 class=""mb-3"">کاتالوگ و جستجوی کتاب‌ها</h3>\n    <form method=""GET"" class=""row g-3"">\n        <div class=""col-md-6"">\n            <input type=""text"" name=""q"" class=""form-control"" placeholder=""جستجوی عنوان کتاب..."" value=""{{ query }}"">\n        </div>\n        <div class=""col-md-4"">\n            <select name=""category"" class=""form-select"">\n                <option value="""">همه دسته‌بندی‌ها</option>\n                {% for cat in categories %}\n                    <option value=""{{ cat.id }}"" {% if selected_category == cat.id|stringformat:'s' %}selected{% endif %}>{{ cat.name }}</option>\n                {% endfor %}\n            </select>\n        </div>\n        <div class=""col-md-2"">\n            <button type=""submit"" class=""btn btn-primary w-100"">فیلتر</button>\n        </div>\n    </form>\n</div>\n\n<div class=""card shadow-sm p-3"">\n    <table class=""table table-hover align-middle"">\n        <thead class=""table-light"">\n            <tr>\n                <th>عنوان</th>\n                <th>نویسنده</th>\n                <th>دسته‌بندی</th>\n                <th>ناشر</th>\n                <th>سال انتشار</th>\n                <th>موجودی</th>\n            </tr>\n        </thead>\n        <tbody>\n            {% for book in books %}\n            <tr>\n                <td class=""fw-bold"">{{ book.title }}</td>\n                <td>{{ book.author }}</td>\n                <td><span class=""badge bg-secondary"">{{ book.category.name }}</span></td>\n                <td>{{ book.publisher|default:""-"" }}</td>\n                <td>{{ book.publication_year|default:""-"" }}</td>\n                <td>\n                    {% if book.available_copies > 0 %}\n                        <span class=""badge bg-success"">{{ book.available_copies }} جلد</span>\n                    {% else %}\n                        <span class=""badge bg-danger"">ناموجود</span>\n                    {% endif %}\n                </td>\n            </tr>\n            {% empty %}\n            <tr>\n                <td colspan=""6"" class=""text-center text-muted py-4"">هیچ کتابی ثبت نشده یا یافت نشد.</td>\n            </tr>\n            {% endfor %}\n        </tbody>\n    </table>\n</div>\n{% endblock %}"""; open(path, "w", encoding="utf-8").write(html); print("SUCCESSFUL")
